<?php use App\Core\CSRF; $days=[1=>'Seg',2=>'Ter',3=>'Qua',4=>'Qui',5=>'Sex',6=>'Sáb',7=>'Dom']; ?>
<div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1">Boxes, vagas e elevadores</h1><p class="text-secondary mb-0">Capacidade física da operação automotiva.</p></div><a href="/auto" class="btn btn-outline-secondary">Dashboard</a></div>
<div class="row g-4"><div class="col-lg-5"><div class="card"><div class="card-header"><strong>Novo recurso</strong></div><div class="card-body"><form method="post" action="/auto/bays" class="row g-3"><?=CSRF::field()?><div class="col-12"><label class="form-label">Nome</label><input name="name" class="form-control" required placeholder="Box 01"></div><div class="col-md-6"><label class="form-label">Tipo</label><select name="bay_type" class="form-select"><option value="box">Box</option><option value="lavagem">Lavagem</option><option value="detailing">Detailing</option><option value="elevador">Elevador</option><option value="secagem">Secagem</option><option value="vaga">Vaga</option><option value="outro">Outro</option></select></div><div class="col-md-6"><label class="form-label">Intervalo</label><input type="number" min="0" max="240" name="buffer_minutes" value="10" class="form-control"><div class="form-text">Minutos entre reservas.</div></div><div class="col-12"><label class="form-label">Serviços aceitos</label><select name="service_ids[]" class="form-select" multiple size="6"><?php foreach($services as $s):?><option value="<?=(int)$s['id']?>"><?=htmlspecialchars($s['name'])?></option><?php endforeach;?></select><div class="form-text">Sem seleção = aceita todos.</div></div><div class="col-12"><label class="form-label">Observações</label><textarea name="notes" class="form-control"></textarea></div><div class="col-12 form-check ms-2"><input type="checkbox" name="active" value="1" checked class="form-check-input" id="bayActive"><label class="form-check-label" for="bayActive">Ativo</label></div><div class="col-12"><button class="btn btn-primary">Cadastrar</button></div></form></div></div></div>
<div class="col-lg-7"><div class="d-grid gap-3"><?php foreach($bays as $b):?><div class="card"><div class="card-body"><div class="d-flex justify-content-between align-items-start"><div><h2 class="h5 mb-1"><?=htmlspecialchars($b['name'])?></h2><span class="badge text-bg-<?=$b['active']?'success':'secondary'?>"><?=htmlspecialchars($b['bay_type'])?></span> <span class="text-secondary small"><?=(int)$b['current_jobs']?> em operação</span></div></div><hr><form method="post" action="/auto/bays/<?=(int)$b['id']?>/hours" class="row g-2"><?=CSRF::field()?><?php foreach($days as $d=>$label):$row=null;foreach($hours[(int)$b['id']]??[] as $h)if((int)$h['weekday']===$d){$row=$h;break;}?><div class="col-2 small pt-2"><?=$label?></div><div class="col-5"><input type="time" class="form-control form-control-sm" name="start_<?=$d?>" value="<?=$row?substr($row['start_time'],0,5):''?>"></div><div class="col-5"><input type="time" class="form-control form-control-sm" name="end_<?=$d?>" value="<?=$row?substr($row['end_time'],0,5):''?>"></div><?php endforeach;?><div class="col-12 mt-3"><button class="btn btn-sm btn-outline-primary">Salvar horários</button></div></form></div></div><?php endforeach;?><?php if(!$bays):?><div class="alert alert-info">Cadastre o primeiro box para começar a agenda automotiva.</div><?php endif;?></div></div></div>
